  # Linux-only formula (rules_brew plan 0006 rows 6.4/6.8,
  # the row-6.10 amendment): the :linux requirement owns the
  # mac refusal -- never a readall-fatal raise.
  depends_on :linux

  def install
    bin.install "klash"

    # Ad-hoc codesign on macOS. This is INTENTIONAL and load-bearing, not a
    # workaround: the binary is unsigned, and macOS refuses to exec an unsigned
    # or stale-signed Mach-O. Writing the file also invalidates any prior
    # signature, so it must be re-signed after install.
    #
    # chmod first: Homebrew stages files read-only, and both xattr and codesign
    # need to WRITE to the binary (xattr fails with EACCES otherwise).
    if OS.mac?
      chmod 0755, bin/"klash"
      system "/usr/bin/xattr", "-cr", bin/"klash"
      system "/usr/bin/codesign", "--force", "--sign", "-", bin/"klash"
    end

    # The default invocation `<bin> complete --print <shell>`
    # writes the script to STDOUT and installs nothing; a
    # `complete` that edits the user's rc file is a
    # formula must-not. A CLI whose `complete` verb
    # takes the shell as a bare POSITIONAL and always prints
    # overrides the invocation args (the surf shape, plan
    # 0009) and rides the same stanza.
    #
    # generate_completions_from_executable appends the shell name as the
    # final argument and writes each script where brew expects it, so it
    # replaces one hand-rolled safe_popen_read per shell.
    generate_completions_from_executable(
      bin/"klash",
      "complete",
      "--print",
      shells: [:zsh],
    )
  end

  def post_install
    linked = HOMEBREW_PREFIX/"bin/klash"
    if linked.exist? && !linked.symlink?
      opoo <<~EOS
        Replacing a non-Homebrew klash at #{linked}.
        That file was almost certainly left by the legacy install script.
        The Homebrew-managed klash is now the one on your PATH.
      EOS
      linked.unlink
    end

    # Idempotent, and also repairs the case where the legacy binary was
    # deleted by hand: brew never created the symlink, so the tool was
    # missing from PATH entirely.
    linked.make_relative_symlink(bin/"klash") unless linked.symlink?
  end


  def caveats
